import { flyGeospatialCameraToAsync } from "@babylonjs/lite";
import type { GeospatialCamera, SceneContext } from "@babylonjs/lite";

export interface Place {
  yaw: number;
  pitch: number;
  radius: number;
  center: { x: number; y: number; z: number };
}

interface ActiveFlight {
  settled: boolean;
  resolve: (arrived: boolean) => void;
}

const activeFlights = new WeakMap<GeospatialCamera, ActiveFlight>();

function angleDelta(a: number, b: number): number {
  let d = a - b;
  // normalize to [-PI, PI]
  d = ((d + Math.PI) % (2 * Math.PI) + 2 * Math.PI) % (2 * Math.PI) - Math.PI;
  return Math.abs(d);
}

function vectorDistance(a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }): number {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  const dz = a.z - b.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

function isAtPlace(camera: GeospatialCamera, place: Place): boolean {
  const angleTolerance = 0.001;
  const planetRadius = camera.limits.planetRadius;
  const lengthTolerance = Math.max(0.001, planetRadius * 1e-5);
  return (
    angleDelta(camera.yaw, place.yaw) <= angleTolerance &&
    Math.abs(camera.pitch - place.pitch) <= angleTolerance &&
    Math.abs(camera.radius - place.radius) <= lengthTolerance &&
    vectorDistance(camera.center, place.center) <= lengthTolerance
  );
}

export function flyToPlace(
  camera: GeospatialCamera,
  scene: SceneContext,
  place: Place,
  durationMs: number
): Promise<boolean> {
  const previous = activeFlights.get(camera);
  if (previous && !previous.settled) {
    previous.settled = true;
    previous.resolve(false);
    camera._cancelFly?.();
  }

  let resolve!: (arrived: boolean) => void;
  const promise = new Promise<boolean>((res) => {
    resolve = res;
  });
  const flight: ActiveFlight = { settled: false, resolve };
  activeFlights.set(camera, flight);

  flyGeospatialCameraToAsync(camera, scene, {
    yaw: place.yaw,
    pitch: place.pitch,
    radius: place.radius,
    center: place.center,
    durationMs,
  })
    .then(() => {
      if (!flight.settled) {
        flight.settled = true;
        resolve(isAtPlace(camera, place));
      }
    })
    .catch(() => {
      if (!flight.settled) {
        flight.settled = true;
        resolve(false);
      }
    });

  return promise;
}
```

