import { flyGeospatialCameraToAsync } from "@babylonjs/lite";
import type { GeospatialCamera, SceneContext } from "@babylonjs/lite";

export interface Place {
  yaw: number;
  pitch: number;
  radius: number;
  center: { x: number; y: number; z: number };
}

interface ActiveFlight {
  settled: boolean;
  resolve: (arrived: boolean) => void;
}

const activeFlights = new WeakMap<GeospatialCamera, ActiveFlight>();

function angleDifference(a: number, b: number): number {
  const delta = a - b;
  const normalized = ((delta + Math.PI) % (2 * Math.PI) + 2 * Math.PI) % (2 * Math.PI) - Math.PI;
  return Math.abs(normalized);
}

function distance(a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }): number {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  const dz = a.z - b.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

function isAtPlace(camera: GeospatialCamera, place: Place): boolean {
  const angleTolerance = 0.001;
  const distanceTolerance = Math.max(0.001, camera.limits.planetRadius * 1e-3);
  return (
    angleDifference(camera.yaw, place.yaw) <= angleTolerance &&
    Math.abs(camera.pitch - place.pitch) <= angleTolerance &&
    Math.abs(camera.radius - place.radius) <= distanceTolerance &&
    distance(camera.center, place.center) <= distanceTolerance
  );
}

export function flyToPlace(
  camera: GeospatialCamera,
  scene: SceneContext,
  place: Place,
  durationMs: number
): Promise<boolean> {
  const previous = activeFlights.get(camera);
  if (previous && !previous.settled) {
    previous.settled = true;
    previous.resolve(false);
  }

  try {
    camera._cancelFly?.();
  } catch {
    // A failing cancel should not prevent a new flight from starting.
  }

  let resolve!: (arrived: boolean) => void;
  const promise = new Promise<boolean>((res) => {
    resolve = res;
  });
  const flight: ActiveFlight = { settled: false, resolve };
  activeFlights.set(camera, flight);

  const duration = Number.isFinite(durationMs) ? Math.max(0, durationMs) : 0;

  let flyPromise: Promise<void>;
  try {
    flyPromise = flyGeospatialCameraToAsync(camera, scene, {
      yaw: place.yaw,
      pitch: place.pitch,
      radius: place.radius,
      center: { x: place.center.x, y: place.center.y, z: place.center.z },
      durationMs: duration,
    });
  } catch {
    if (!flight.settled) {
      flight.settled = true;
      resolve(false);
    }
    return promise;
  }

  flyPromise
    .then(() => {
      if (!flight.settled) {
        flight.settled = true;
        resolve(isAtPlace(camera, place));
      }
    })
    .catch(() => {
      if (!flight.settled) {
        flight.settled = true;
        resolve(false);
      }
    });

  return promise;
}
```

